/// Release notes for people, newest first. Every change that reaches main is a new release:
/// add an entry on top with the next id and a higher version. The app's version comes from the
/// top entry, the update badge compares it with GitHub, and CI refuses a pull request without one.
public enum WhatsNewCatalog {
    public static let releases: [WhatsNewRelease] = [
        WhatsNewRelease(id: 22, version: "0.14.0", title: "Choose what Space removes", items: [
            WhatsNewRelease.Item(symbol: "checklist", title: "Review lists with checkboxes", text: "Every clean-up category except Captures has Review… It lists what is inside with a size and a checkbox each; tick what goes and press the button at the bottom, which says how many items and how much space. Caches are deleted for good, since the tools download or build them again; project folders go to the Trash. Bugbear asks once more, and checks every item again right before it removes it. Anything that changed since the scan is left alone and listed with the reason. Folders tracked by git are left out of the list.", shortcut: "Menu → Space", image: "space-review"),
            WhatsNewRelease.Item(symbol: "folder.badge.minus", title: "Project folders to the Trash", text: "Find projects in the Disk Space window searches your project folders for node_modules, Python environments, Pods, Rust and Swift build folders and Gradle folders. Only the ones in projects you have not touched for 30 days are ticked, and they go to the Trash, so you can put them back. After a removal, Delete … for good asks once more and then deletes only what Bugbear moved there.", shortcut: "Disk Space window"),
            WhatsNewRelease.Item(symbol: "externaldrive", title: "More caches", text: "Space lists the uv, Bun, Go modules, Maven, Hugging Face, pre-commit, Cursor and VS Code, and Playwright caches. Each one says what comes back when it is needed. Maven rows start unticked, since libraries you installed yourself may not come back.", shortcut: "Menu → Space"),
            WhatsNewRelease.Item(symbol: "slider.horizontal.3", title: "Project clean-up in Settings", text: "Settings → Storage has a Project clean-up group: the folders to search inside your home folder (not in Library), after how many days a project counts as old, Trash or delete at once, which kinds of folders to look for, and which extra caches to show.", shortcut: "Settings → Storage"),
            WhatsNewRelease.Item(symbol: "cpu", title: "Lighter area recording", text: "Recording an area takes less CPU: only the displays the area covers are recorded at full resolution, the others keep the buffer's lower resolution.", shortcut: "⌥⇧6"),
        ]),
        WhatsNewRelease(id: 21, version: "0.13.1", title: "Library updates", items: [
            WhatsNewRelease.Item(symbol: "shippingbox", title: "Newer YAML parser", text: "YAML in the toolbox (format and convert) uses Yams 6. It works the same as before.", shortcut: "Toolbox"),
        ]),
        WhatsNewRelease(id: 20, version: "0.13.0", title: "Put the area where you need it", items: [
            WhatsNewRelease.Item(symbol: "hand.draw", title: "Move the area while recording", text: "The frame of an area recording has a grip above it: drag it to move the whole area without stopping, the size stays. Clicks inside the area still go to the app under it. The video gets the area where it is when you stop.", shortcut: "⌥⇧6", image: "record-area-move"),
            WhatsNewRelease.Item(symbol: "rectangle.split.2x1", title: "An area across two displays", text: "With more than one display the area picker covers all of them: draw or drag the area onto another display, or across two. While recording the grip takes it there too. The video has both parts in their places, as sharp as the sharper display. Everything outside the area stays out.", shortcut: "⌥⇧6", image: "record-area-across"),
            WhatsNewRelease.Item(symbol: "arrow.up.and.down.and.arrow.left.and.right", title: "Easier area picking", text: "The area picker has the same grip above the frame to move the area, handles on the edges too, not only on the corners, and the pointer shows what a drag does: a hand to move the area, arrows to resize it, a cross to draw a new one.", shortcut: "Area picker"),
            WhatsNewRelease.Item(symbol: "textformat.size", title: "Mark size in the video editor", text: "The video editor's toolbar has a size, as the screenshot editor's does: it resizes the selected text, arrow or box, and with nothing selected sets the size of the next one. The editor remembers it for the next clip.", shortcut: "+ and -", image: "video-mark-size"),
            WhatsNewRelease.Item(symbol: "lock.shield", title: "One window for Allow", text: "Allow… for Screen Recording or Accessibility opened System Settings and macOS's own window at the same time. Now the first press shows macOS's window, and later ones open System Settings.", shortcut: "Settings → Permissions"),
            WhatsNewRelease.Item(symbol: "folder", title: "Tidier scripts", text: "For building from source: the scripts sit in folders now, test runs in scripts/test, CI checks in scripts/check and tools in scripts/dev. install.sh, update.sh, uninstall.sh and build-app.sh stay where they were. Installing a build with another bundle id also removes the old one's permissions, so System Settings lists \(AppInfo.name) once.", shortcut: "Terminal"),
        ]),
        WhatsNewRelease(id: 19, version: "0.12.0", title: "Pick the part that matters", items: [
            WhatsNewRelease.Item(symbol: "crop", title: "Crop a clip", text: "Crop in the video editor shows the whole screen: drag the edges or draw the part to keep, then Done. The saved video is only that part; marks, clicks and blur stay where they were on the picture. Reset brings the whole screen back.", shortcut: "Video editor", image: "video-crop"),
            WhatsNewRelease.Item(symbol: "textformat", title: "Write on the screen", text: "Drawing on the screen has Text now: click where the note goes and type, in any keyboard layout. Return keeps it, Esc drops it. Like other marks it is in the recording and fades unless pinned.", shortcut: "⌥⇧A", image: "draw-text"),
            WhatsNewRelease.Item(symbol: "arrow.up.left.and.arrow.down.right", title: "Resize the area while recording", text: "The frame of an area recording has handles now. Drag a corner or an edge to make the area bigger or smaller without stopping; the video gets the area as it is when you stop. After you pick the area, the app you were in is in front again, so you can go on right away.", shortcut: "⌥⇧6", image: "record-area-resize"),
            WhatsNewRelease.Item(symbol: "arrow.clockwise.circle", title: "Back after a closed lid", text: "When the displays went away (the lid closed, a monitor was unplugged, the Mac went to sleep), the buffer could stay on \"Buffer error: No display available for capture\" until you turned it on again. Now it keeps trying and starts again by itself as soon as a display is back or the Mac wakes up.", shortcut: "Buffer"),
        ]),
        WhatsNewRelease(id: 18, version: "0.11.0", title: "Steps you can paste", items: [
            WhatsNewRelease.Item(symbol: "sparkles", title: "A new look", text: "Glass panels over a soft gradient, colored icons for every tab, action and section, a glowing 1 min button, a disk ring on the Space tab, and captures sorted by day with apps in a sidebar.", shortcut: "Everywhere", image: "aurora-menu"),
            WhatsNewRelease.Item(symbol: "sidebar.left", title: "Settings in sections", text: "Settings has a sidebar now: General, Buffer and recording, Bug reports, Storage, Shortcuts, Updates and feedback. Each page holds only what belongs together.", shortcut: "Settings"),
            WhatsNewRelease.Item(symbol: "arrow.up.right", title: "Arrow with text", text: "A new tool right after the arrow: drag it to the problem and type the note at once, right at its tail. The note sits on the side the arrow comes from; left empty, a plain arrow stays.", shortcut: "K"),
            WhatsNewRelease.Item(symbol: "rectangle.and.text.magnifyingglass", title: "Every field on the overlay", text: "The environment overlay on screenshots and clips now has Device, Locale and Appearance too, not only some of the fields. Turn any of them off in Settings → Bug reports.", shortcut: "Overlay on image"),
            WhatsNewRelease.Item(symbol: "slider.horizontal.3", title: "Edit the environment from the menu", text: "Edit next to Environment in the menu opens the report fields in Settings, and with every field off the menu says so instead of showing an empty card.", shortcut: "Menu → Capture"),
            WhatsNewRelease.Item(symbol: "lock.shield", title: "Permissions in Settings", text: "A Permissions page shows every permission, whether it is given and what it is for, with Allow… for the missing ones and Open… to check one in System Settings. It also tells when a browser does not let \(AppInfo.name) read the URL.", shortcut: "Settings → Permissions", image: "settings-permissions"),
            WhatsNewRelease.Item(symbol: "checklist", title: "Choose the report fields", text: "Bug reports lists every field \(AppInfo.name) fills in, like macOS, Device, URL and Time, with what it holds. Turn one off or rename it, and add your own with New field or a ready one like + Stand. Edit next to Environment in the editors opens it, and the open capture follows what you change.", shortcut: "Settings → Bug reports", image: "settings-fields"),
            WhatsNewRelease.Item(symbol: "list.number", title: "Steps say what you did", text: "Bug report steps now name the field you typed into and add a step for every page you open: Open shop.test/login, Type text in \"Email\" text field, Click \"Sign in\" button. Copy them from the editor as Markdown or Jira; the button shows how many steps the report has. The report goes straight to the steps, without times, Summary or file paths, and Space or Delete while typing stays in the same step.", shortcut: "Copy report", image: "steps"),
            WhatsNewRelease.Item(symbol: "character.cursor.ibeam", title: "What you typed, if you want", text: "Turn on Show what I type in steps, and steps include the text: Type \"john@test.com\" in \"Email\" text field. It is off until you choose it; password fields are never read.", shortcut: "Settings → Buffer and recording"),
            WhatsNewRelease.Item(symbol: "captions.bubble", title: "Steps on the video", text: "Show steps in the video editor puts the current step at the bottom of the clip, so whoever watches knows what was clicked and typed.", shortcut: "Video editor"),
            WhatsNewRelease.Item(symbol: "menubar.rectangle", title: "The bear stays in sight", text: "On a Mac with a notch, macOS hid the bear behind it when the menu bar was full or a display was unplugged. \(AppInfo.name) now moves it next to the system icons, and ⌥⇧B opens its menu from anywhere.", shortcut: "⌥⇧B"),
            WhatsNewRelease.Item(symbol: "lock.shield", title: "What each permission is for", text: "The welcome guide shows examples under every permission: Screen Recording for ⌥⇧1 and screenshots, Accessibility for steps, ⌘C in clips and scrolling screenshots.", shortcut: "Welcome guide"),
            WhatsNewRelease.Item(symbol: "keyboard", title: "Shortcuts in any keyboard layout", text: "⌘V to paste a picture, ⌘Z, tool letters in the editors and ⌘C on the ruler now work with a Russian or any other layout, and clips show ⌘C, not ⌘С.", shortcut: "⌘V"),
            WhatsNewRelease.Item(symbol: "dock.rectangle", title: "The Dock icon does something", text: "A click on \(AppInfo.name)'s Dock icon brings its windows back. With none left it opens the menu, and the icon leaves the Dock. Quit & Reopen in System Settings now opens \(AppInfo.name) again too.", shortcut: "Dock"),
            WhatsNewRelease.Item(symbol: "sidebar.right", title: "A simpler side panel", text: "Style preset is gone from the screenshot editor: the colors and +/- in the toolbar do the same, and Layers sits higher.", shortcut: "Screenshot editor"),
            WhatsNewRelease.Item(symbol: "lineweight", title: "Bolder marks", text: "Arrows, boxes and pens start at size 7 on screenshots and when drawing on the screen, easier to see on a busy page.", shortcut: "Screenshot editor"),
            WhatsNewRelease.Item(symbol: "scribble.variable", title: "Marks on clips that show", text: "Text, arrows, boxes and blur added at the end of a clip lasted a split second, and dragging could slide a mark off the video. Now a mark lasts 3 s, only moves when you drag it, and stays in the frame; clips saved before are fixed when opened. Click with Text and type right on the video (double-click to change it), and an arrow shows as you drag it.", shortcut: "Video editor"),
            WhatsNewRelease.Item(symbol: "hand.draw", title: "Easier scrubbing", text: "Drag the playhead from its handle or anywhere along the video frames, and grab the trim edges without aiming for a thin line.", shortcut: "Video editor"),
            WhatsNewRelease.Item(symbol: "accessibility", title: "VoiceOver reads every button", text: "Icon buttons now say what they do: the swap, eyedropper and copy buttons in the toolbox, the step guide arrows, the Disk Space rows, the capture cards in history, the area picker buttons, the bug report format arrow, the display picker in the editors and the update badge.", shortcut: "VoiceOver"),
            WhatsNewRelease.Item(symbol: "doc.text.magnifyingglass", title: "System log in the open clip", text: "The app's system log is saved a few seconds after a clip; its button now shows up in the editor that is already open, not only the next time.", shortcut: "Video editor"),
            WhatsNewRelease.Item(symbol: "play.rectangle.on.rectangle", title: "Compared clips play together", text: "In Compare, the two clips no longer have their own play buttons that could pull them apart: Play both and the position slider keep them on the same moment.", shortcut: "Compare"),
            WhatsNewRelease.Item(symbol: "trash", title: "Uninstall in one command", text: "scripts/uninstall.sh removes \(AppInfo.name) completely: the app, captures, logs, settings, caches, permissions and the login item. It shows what goes and asks first; your saved files stay.", shortcut: "Terminal"),
            WhatsNewRelease.Item(symbol: "arrow.down.circle", title: "Updates always from main", text: "A copy built from a branch that was merged and deleted said \"HTTP 404\" when checking for updates. Updates now always come from the main branch.", shortcut: "Menu bar"),
            WhatsNewRelease.Item(symbol: "rectangle.inset.filled.and.person.filled", title: "The purple icon goes away", text: "Quitting, updating or reinstalling \(AppInfo.name) stops the screen capture first, so macOS no longer shows \(AppInfo.name) as \"Currently Sharing\" after it is gone.", shortcut: "Quit"),
            WhatsNewRelease.Item(symbol: "hand.wave", title: "Welcome back", text: "Installing \(AppInfo.name) where it was deleted shows the welcome guide again, like for anyone new. Updates keep your settings.", shortcut: "Welcome guide", image: "welcome-guide"),
            WhatsNewRelease.Item(symbol: "exclamationmark.triangle", title: "Crash clips stay", text: "Updating from a version before 0.9.0 now keeps all your crash clips until you pick a time in Settings, as intended; before, they were deleted after 7 days. The time you pick in the welcome guide is now saved as your choice.", shortcut: "Settings → Storage"),
            WhatsNewRelease.Item(symbol: "lock", title: "Option typing stays private", text: "Characters typed with Option, like ™ or letters on many keyboard layouts, now show as \"typing…\" in clips, the same as other typing. Shortcuts with ⌘ or ⌃ still show.", shortcut: "Clips"),
        ]),
        WhatsNewRelease(id: 17, version: "0.10.1", title: "Lighter recording", items: [
            WhatsNewRelease.Item(symbol: "gauge.with.dots.needle.33percent", title: "Recording takes a fifth of the CPU", text: "On a still screen recording now takes about 5% of the CPU instead of 26%: the recording bar no longer redraws the whole bar four times a second, and frames where only the menu bar or the bar changed are not encoded thirty times a second.", shortcut: "Recording"),
            WhatsNewRelease.Item(symbol: "rectangle.inset.filled.and.person.filled", title: "About the purple icon", text: "The welcome guide now explains the purple icon macOS shows in the menu bar while the screen is captured: it is the system's own sign, and nothing leaves your Mac.", shortcut: "Welcome guide"),
        ]),
        WhatsNewRelease(id: 16, version: "0.10.0", title: "Tell us what broke", items: [
            WhatsNewRelease.Item(symbol: "exclamationmark.bubble", title: "Report a problem or suggest a feature", text: "The new button in the menu opens a GitHub issue with the version, macOS and the last log lines already filled in, and saves the full logs as a zip to drag into it. Your home folder and user name are hidden.", shortcut: "Menu"),
        ]),
        WhatsNewRelease(id: 15, version: "0.9.1", title: "Steadier display switching", items: [
            WhatsNewRelease.Item(symbol: "rectangle.on.rectangle", title: "Picking the shown display", text: "Choosing the display a clip or screenshot already shows could fail with \"Invalid argument\" and leave a stray file. Now it just stays as it is.", shortcut: "Editor"),
        ]),
        WhatsNewRelease(id: 14, version: "0.9.0", title: "Tooltips everywhere, a calmer palette", items: [
            WhatsNewRelease.Item(symbol: "text.bubble", title: "Tooltips that show up", text: "Hover any button for a moment to see what it does, in the editors and in the menu bar panel, even while another app is in front.", shortcut: "Hover"),
            WhatsNewRelease.Item(symbol: "paintpalette", title: "Five colors that follow you", text: "Five colors and a round button for any color. A picked color takes the first slot and the others move right; while you drag in the color panel only that slot changes.", shortcut: "Editors"),
            WhatsNewRelease.Item(symbol: "square.dashed", title: "No fill or Fill, in words", text: "One clear switch for text labels and shape fills, and it changes the text you are typing right away. One size control: text size for text, line width for shapes.", shortcut: "Screenshot editor"),
            WhatsNewRelease.Item(symbol: "keyboard", title: "Shortcuts in words", text: "The guide says Option + Shift + 1 next to ⌥⇧1, and follows the shortcuts you set.", shortcut: "Welcome guide"),
            WhatsNewRelease.Item(symbol: "exclamationmark.triangle", title: "Crash clips keep their time", text: "Choose how long clips saved after a crash stay: 3, 7 or 30 days, or always. Cleaning logs keeps crash reports.", shortcut: "Welcome guide"),
            WhatsNewRelease.Item(symbol: "photo.badge.plus", title: "Pictures on a screenshot", text: "Put another screenshot on top of this one: paste it with ⌘V, drop a file, or pick one. Drag it, resize it by the corners.", shortcut: "⌘V"),
            WhatsNewRelease.Item(symbol: "doc.on.clipboard", title: "You see what was copied", text: "Copying text from the screen, a QR code, a color or a screenshot shows what is on the clipboard and how to paste it.", shortcut: "⌥⇧O"),
            WhatsNewRelease.Item(symbol: "arrow.down.circle", title: "Updates list pull requests", text: "The update badge lists what was merged, each with a link to its pull request.", shortcut: "Menu bar"),
        ]),
        WhatsNewRelease(id: 13, version: "0.8.1", title: "Clear clean-up", items: [
            WhatsNewRelease.Item(symbol: "trash", title: "You see what goes", text: "After Clean the question gets its own line: what is deleted, how much, and full Cancel and Delete buttons instead of squeezed ones.", shortcut: "Space tab"),
        ]),
        WhatsNewRelease(id: 12, version: "0.8.0", title: "Pick the quality, see the size", items: [
            WhatsNewRelease.Item(symbol: "photo", title: "Screenshot quality", text: "Save as PNG, PNG at half size, or JPEG in high, medium or small quality. Each choice shows how big the file comes out.", shortcut: "Screenshot editor"),
            WhatsNewRelease.Item(symbol: "film", title: "Video quality with sizes", text: "Original, 1080p, 720p or the new 480p, each with the expected file size for this clip.", shortcut: "Video editor"),
        ]),
        WhatsNewRelease(id: 11, version: "0.7.0", title: "Friendlier editors", items: [
            WhatsNewRelease.Item(symbol: "paintpalette", title: "Any color, the last four kept", text: "Pick any color next to the palette. The last four picked colors stay there, one click away.", shortcut: "Editors"),
            WhatsNewRelease.Item(symbol: "square.dashed", title: "Transparent or filled", text: "Text with or without a label, rectangles and ellipses as outlines or with a see-through fill. Line and text sizes have − and + buttons.", shortcut: "Screenshot editor"),
            WhatsNewRelease.Item(symbol: "crop", title: "Crop by the edges", text: "Drag the edges and corners to shrink the screenshot, drag inside to move the area. The size shows while you drag.", shortcut: "C"),
            WhatsNewRelease.Item(symbol: "delete.left", title: "Delete works everywhere", text: "Delete removes the selected mark wherever you clicked last in the editor. Undo and redo moved to the left of the toolbar.", shortcut: "Delete"),
            WhatsNewRelease.Item(symbol: "stop.circle", title: "Stopped from the macOS menu", text: "Stop in the purple screen recording icon saves what the buffer holds and offers to open it in the editor.", shortcut: "Menu bar"),
            WhatsNewRelease.Item(symbol: "folder", title: "Your folder, and tooltips", text: "Files go to Desktop/Bugbear unless you pick another folder in the guide or Settings. Every button explains itself when you hover over it.", shortcut: "Welcome guide"),
        ]),
        WhatsNewRelease(id: 10, version: "0.6.0", title: "A new look", items: [
            WhatsNewRelease.Item(symbol: "magnifyingglass", title: "The bear goes bug hunting", text: "A new logo: the bear looks at a bug through a magnifying glass. In the menu bar, the app icon and the installer.", shortcut: "Menu bar"),
        ]),
        WhatsNewRelease(id: 9, version: "0.5.4", title: "Windows fit the screen", items: [
            WhatsNewRelease.Item(symbol: "macwindow", title: "Continue stays in reach", text: "The welcome guide and other windows keep their size and open inside the screen. On tall displays the guide used to stretch past the bottom, out of reach of its Continue button.", shortcut: "Welcome guide"),
        ]),
        WhatsNewRelease(id: 8, version: "0.5.3", title: "Tests leave your \(AppInfo.name) alone", items: [
            WhatsNewRelease.Item(symbol: "arrow.uturn.backward.circle", title: "Your \(AppInfo.name) comes back", text: "The test scripts quit the test copy when they finish and start your installed \(AppInfo.name) again, so a test copy no longer keeps recording in the menu bar.", shortcut: "scripts/e2e.sh"),
        ]),
        WhatsNewRelease(id: 7, version: "0.5.2", title: "Clearer installer", items: [
            WhatsNewRelease.Item(symbol: "wrench.and.screwdriver", title: "Says what to update", text: "On macOS 14.0-14.4 the installer now asks to update macOS first, since Swift 6 needs 14.5.", shortcut: "install.sh"),
        ]),
        WhatsNewRelease(id: 6, version: "0.5.1", title: "Permissions stay after updates without Xcode", items: [
            WhatsNewRelease.Item(symbol: "checkmark.seal", title: "A signature of this Mac's own", text: "Macs without Xcode now sign \(AppInfo.name) with a certificate made just for them, so macOS no longer asks for Screen Recording again after every update.", shortcut: "Automatic"),
        ]),
        WhatsNewRelease(id: 5, version: "0.5.0", title: "Every update is a version", items: [
            WhatsNewRelease.Item(symbol: "number", title: "Versions you can see", text: "Each update has its own version number. This window shows it next to every release, and Settings shows the one you have.", shortcut: "What's new"),
            WhatsNewRelease.Item(symbol: "arrow.down.circle.fill", title: "Update to a version", text: "The menu badge says which version is waiting, and only a real release counts as an update.", shortcut: "Menu bar panel"),
        ]),
        WhatsNewRelease(id: 4, version: "0.4.0", title: "Text without a label, several displays, disk space", items: [
            WhatsNewRelease.Item(symbol: "character", title: "Text on a transparent background", text: "Write on screenshots and videos with outlined letters instead of a colored label. Pick it next to the text size, or under Background in the video editor.", shortcut: "Editors"),
            WhatsNewRelease.Item(symbol: "rectangle.on.rectangle", title: "Every display, your pick", text: "The buffer keeps all displays. In the editor show one display or both side by side, for clips and screenshots.", shortcut: "Editor toolbar"),
            WhatsNewRelease.Item(symbol: "internaldrive", title: "Disk space", text: "See what takes space, clean caches and build leftovers, find the biggest files and move them to the Trash.", shortcut: "Space tab"),
            WhatsNewRelease.Item(symbol: "doc.on.clipboard", title: "Screenshots go to the clipboard", text: "Every screenshot is copied right away, ready to paste into a ticket or a chat.", shortcut: "⌥⇧4"),
        ]),
        WhatsNewRelease(id: 3, version: "0.3.0", title: "Reports for Jira, checks on screen, more tools", items: [
            WhatsNewRelease.Item(symbol: "list.number", title: "Bug report in Jira wiki", text: "Copy bug report now also gives Jira markup: h2 headings, # steps, {{code}}. The last format you pick becomes the default.", shortcut: "Copy bug report ▾"),
            WhatsNewRelease.Item(symbol: "tag", title: "Your fields in every capture", text: "Stand, build, test account, feature flag: set them once and they go into the environment, the badge and the report.", shortcut: "Settings → Bug reports"),
            WhatsNewRelease.Item(symbol: "list.bullet.rectangle.portrait", title: "Step-by-step guide", text: "Select screenshots in All captures and make one numbered guide with captions, as PNG or PDF.", shortcut: "All captures → Select"),
            WhatsNewRelease.Item(symbol: "rectangle.split.2x1", title: "Before and after", text: "Compare two screenshots side by side, with a slider, or with changes boxed in red. Two clips play in sync.", shortcut: "All captures → Select"),
            WhatsNewRelease.Item(symbol: "arrow.down.to.line.compact", title: "Scrolling screenshot", text: "Pick an area: the app scrolls it and glues one long image. Sticky headers and footers appear once.", shortcut: "Capture tab"),
            WhatsNewRelease.Item(symbol: "ruler", title: "Measure, pick colors, check contrast", text: "A ruler in points and pixels, a color picker that copies hex, and a WCAG contrast checker.", shortcut: "Record tab · Toolbox"),
            WhatsNewRelease.Item(symbol: "square.on.square.dashed", title: "Design overlay", text: "Float a Figma export over the real app, set opacity, nudge it with the arrows, click through it.", shortcut: "Record tab"),
            WhatsNewRelease.Item(symbol: "macwindow", title: "Window sizes", text: "Resize the app you test to 1280×720, 1440×900, phone or tablet widths in one click.", shortcut: "Record tab"),
            WhatsNewRelease.Item(symbol: "curlybraces", title: "Five new tools", text: "JSON diff, JSONPath, HTTP request/response parser, cron explainer and exact-length strings for field limits.", shortcut: "Toolbox"),
            WhatsNewRelease.Item(symbol: "keyboard", title: "Your own shortcuts", text: "Change any global shortcut or add new ones, for example for the ruler or the color picker.", shortcut: "Settings → Shortcuts"),
            WhatsNewRelease.Item(symbol: "externaldrive", title: "Automatic clean-up", text: "Delete captures older than 7, 30 or 90 days, or keep them under a size limit.", shortcut: "Settings → Storage"),
        ]),
        WhatsNewRelease(id: 2, version: "0.2.0", title: "Sizes in the editors, clear recording area", items: [
            WhatsNewRelease.Item(symbol: "textformat.size", title: "Bigger and bolder marks", text: "Seven line thicknesses and text from 12 to 100 pt in the screenshot editor. + and - resize the selected mark or the current tool.", shortcut: "+  -"),
            WhatsNewRelease.Item(symbol: "plus.magnifyingglass", title: "Resize marks in videos", text: "Select a text, arrow or box in the video editor and press + or - (50% to 400%). New marks keep the last size.", shortcut: "+  -"),
            WhatsNewRelease.Item(symbol: "rectangle.dashed", title: "Pick the recording size", text: "Record an area at 720p, 1080p, 1440×900, 16:9, 4:3, 1:1, phone size or full screen, or drag your own.", shortcut: "Record → Area…"),
            WhatsNewRelease.Item(symbol: "eye", title: "See what is recorded", text: "While recording, a solid frame marks what is in the video, everything else is dimmed and other displays say Not recorded. None of it is in the video.", shortcut: "While recording"),
        ]),
        WhatsNewRelease(id: 1, version: "0.1.0", title: "Catch, explain and share bugs faster", items: [
            WhatsNewRelease.Item(symbol: "flag.fill", title: "Mark the moment", text: "Saw the bug? Press ⌥⇧M. The next save reaches back to that moment and the editor opens right on it.", shortcut: "⌥⇧M"),
            WhatsNewRelease.Item(symbol: "exclamationmark.triangle.fill", title: "Clips of crashes", text: "When an app you were using crashes, the minute before it is saved to Recent with the crash report. Nothing to press.", shortcut: "Automatic"),
            WhatsNewRelease.Item(symbol: "list.number", title: "Bug report in one click", text: "Copy bug report gives Markdown with steps from your clicks and keys, Expected / Actual, the environment and files.", shortcut: "In the editors"),
